create or replace function public.claim_account_deletion_request(
  p_request_id text,
  p_receipt_hash text,
  p_user_id uuid default null,
  p_lease_id uuid default gen_random_uuid(),
  p_allow_internal boolean default false
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_request public.account_deletion_requests;
begin
  if p_request_id !~ '^[0-9a-f]{64}$'
    or (not p_allow_internal and p_receipt_hash !~ '^[0-9a-f]{64}$') then
    raise exception 'invalid deletion request';
  end if;
  if not p_allow_internal and p_user_id is null then
    return jsonb_build_object('claimed', false, 'reason', 'authentication_required');
  end if;

  if p_user_id is not null then
    select * into v_request
    from public.account_deletion_requests
    where user_id = p_user_id
    for update;

    if found and v_request.request_id <> p_request_id then
      if v_request.sessions_revoked_at is not null then
        return jsonb_build_object(
          'claimed', false,
          'reason', 'existing_request_after_revocation'
        );
      end if;
      update public.account_deletion_requests
      set request_id = p_request_id,
          receipt_hash = p_receipt_hash,
          receipt_expires_at = now() + interval '24 hours',
          state = 'requested',
          lease_id = null,
          lease_until = null,
          attempts = 0,
          sessions_revoked_at = null,
          storage_deleted_at = null,
          auth_deleted_at = null,
          completed_at = null,
          storage_pending_prefixes = jsonb_build_array(p_user_id::text),
          last_error_code = null,
          updated_at = now()
      where user_id = p_user_id;
    elsif not found then
      insert into public.account_deletion_requests (
        request_id, user_id, receipt_hash, receipt_expires_at, state,
        storage_pending_prefixes, updated_at
      ) values (
        p_request_id, p_user_id, p_receipt_hash, now() + interval '24 hours',
        'requested', jsonb_build_array(p_user_id::text), now()
      ) on conflict (request_id) do nothing;
    end if;
  end if;

  select * into v_request
  from public.account_deletion_requests
  where request_id = p_request_id
    and (
      p_allow_internal
      or (
        p_user_id is not null
        and user_id = p_user_id
        and receipt_hash = p_receipt_hash
        and receipt_expires_at > now()
      )
    )
  for update;

  if not found then
    return jsonb_build_object('claimed', false, 'reason', 'not_found_or_expired');
  end if;
  if v_request.state = 'completed' then
    return jsonb_build_object(
      'claimed', false, 'completed', true, 'state', v_request.state
    );
  end if;
  if v_request.state = 'failed' then
    return jsonb_build_object(
      'claimed', false, 'completed', false, 'state', v_request.state,
      'reason', coalesce(v_request.last_error_code, 'failed')
    );
  end if;
  if v_request.attempts >= 100 then
    update public.account_deletion_requests
    set state = 'failed',
        lease_id = null,
        lease_until = null,
        last_error_code = 'retry_budget_exhausted',
        updated_at = now()
    where request_id = p_request_id;
    return jsonb_build_object(
      'claimed', false, 'completed', false, 'state', 'failed',
      'reason', 'retry_budget_exhausted'
    );
  end if;
  if v_request.lease_until is not null and v_request.lease_until > now() then
    return jsonb_build_object(
      'claimed', false, 'state', v_request.state, 'retry', true
    );
  end if;

  update public.account_deletion_requests
  set lease_id = p_lease_id,
      lease_until = now() + interval '90 seconds',
      attempts = attempts + 1,
      last_stage_started_at = now(),
      updated_at = now()
  where request_id = p_request_id;

  return jsonb_build_object(
    'claimed', true,
    'leaseId', p_lease_id,
    'state', v_request.state,
    'userId', v_request.user_id,
    'sessionsRevoked', v_request.sessions_revoked_at is not null,
    'storageDeleted', v_request.storage_deleted_at is not null,
    'storagePendingPrefixes', v_request.storage_pending_prefixes
  );
end;
$$

create or replace function public.read_account_deletion_status(
  p_request_id text,
  p_receipt_hash text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_request public.account_deletion_requests;
begin
  if p_request_id !~ '^[0-9a-f]{64}$'
    or p_receipt_hash !~ '^[0-9a-f]{64}$' then
    return null;
  end if;
  select * into v_request
  from public.account_deletion_requests
  where request_id = p_request_id
    and receipt_hash = p_receipt_hash
    and receipt_expires_at > now();
  if not found then return null; end if;
  return jsonb_build_object(
    'accepted', true,
    'completed', v_request.state = 'completed',
    'state', v_request.state,
    'retry', v_request.state not in ('completed', 'failed'),
    'receiptExpiresAt', v_request.receipt_expires_at
  );
end;
$$

create or replace function public.reconcile_google_play_one_time(
  p_purchase_token_hash text,
  p_product_id text,
  p_order_id text,
  p_event_key text,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_binding public.purchase_bindings;
  v_result jsonb;
begin
  if p_product_id not in (
    'chronospark_lifetime',
    'chronospark_credits_100',
    'chronospark_credits_500',
    'chronospark_credits_1200',
    'chronospark_credits_3000'
  ) then
    return jsonb_build_object('applied', false, 'reason', 'unsupported_product');
  end if;
  select * into v_binding
  from public.purchase_bindings
  where token_hash = p_purchase_token_hash
  for update;
  if not found or v_binding.product_id <> p_product_id then
    return jsonb_build_object('applied', false, 'reason', 'binding_not_found');
  end if;
  if p_event_key is not null and exists (
    select 1 from public.monetization_entitlement_events
    where event_key = p_event_key
  ) then
    return jsonb_build_object(
      'applied', true, 'duplicate', true, 'userId', v_binding.user_id
    );
  end if;

  v_result := public.apply_verified_purchase(
    v_binding.user_id,
    p_product_id,
    'inapp',
    p_purchase_token_hash,
    p_order_id,
    now(),
    null,
    p_payload || jsonb_build_object('_edge_event_key', p_event_key)
  );

  update public.monetization_entitlement_events
  set event_key = p_event_key
  where user_id = v_binding.user_id
    and event_key is null
    and metadata ->> '_edge_event_key' = p_event_key;

  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object(
    'userId', v_binding.user_id
  );
end;
$$

create or replace function public.migrate_google_play_purchase_binding(
  p_old_purchase_token_hash text,
  p_new_purchase_token_hash text,
  p_product_id text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_old public.purchase_bindings;
  v_new public.purchase_bindings;
begin
  if p_old_purchase_token_hash !~ '^[0-9a-f]{64}$'
    or p_new_purchase_token_hash !~ '^[0-9a-f]{64}$'
    or p_product_id not in (
      'chronospark_premium_monthly', 'chronospark_premium_annual'
    ) then
    return jsonb_build_object('migrated', false, 'reason', 'invalid_input');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_old_purchase_token_hash, 0));
  select * into v_old
  from public.purchase_bindings
  where token_hash = p_old_purchase_token_hash;
  if not found then
    return jsonb_build_object('migrated', false, 'reason', 'old_binding_not_found');
  end if;

  insert into public.purchase_bindings (token_hash, user_id, product_id)
  values (p_new_purchase_token_hash, v_old.user_id, p_product_id)
  on conflict (token_hash) do nothing;

  select * into v_new
  from public.purchase_bindings
  where token_hash = p_new_purchase_token_hash;
  if not found or v_new.user_id <> v_old.user_id then
    return jsonb_build_object('migrated', false, 'reason', 'binding_conflict');
  end if;
  return jsonb_build_object('migrated', true, 'userId', v_old.user_id);
end;
$$

-- Server-managed, multi-device Firebase Cloud Messaging registrations.
-- Client callers can only claim or release their current installation through
-- the narrowly granted RPCs below; raw tokens are never exposed through the
-- Data API to anon or authenticated roles.

create table public.firebase_device_registrations (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  installation_id text not null,
  token text not null,
  platform text not null,
  source text not null,
  created_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  constraint firebase_device_registrations_installation_id_length
    check (char_length(installation_id) between 20 and 128),
  constraint firebase_device_registrations_token_length
    check (char_length(token) between 16 and 4096),
  constraint firebase_device_registrations_platform
    check (platform in ('android', 'ios', 'web', 'macos', 'windows', 'linux')),
  constraint firebase_device_registrations_source_length
    check (char_length(source) between 1 and 64),
  constraint firebase_device_registrations_installation_id_key
    unique (installation_id),
  constraint firebase_device_registrations_token_key unique (token)
);

create index firebase_device_registrations_user_last_seen_idx
  on public.firebase_device_registrations (user_id, last_seen_at desc);

alter table public.firebase_device_registrations enable row level security;

revoke all on table public.firebase_device_registrations
  from public, anon, authenticated, service_role;
revoke all on sequence public.firebase_device_registrations_id_seq
  from public, anon, authenticated, service_role;

grant select, insert, update, delete
  on table public.firebase_device_registrations to service_role;
grant usage, select
  on sequence public.firebase_device_registrations_id_seq to service_role;

create or replace function public.register_firebase_device(
  p_installation_id text,
  p_token text,
  p_platform text,
  p_source text
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_installation_id text := pg_catalog.btrim(p_installation_id);
  v_token text := pg_catalog.btrim(p_token);
  v_platform text := pg_catalog.lower(pg_catalog.btrim(p_platform));
  v_source text := pg_catalog.btrim(p_source);
  v_registration_id bigint;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required.';
  end if;
  if pg_catalog.char_length(v_installation_id) not between 20 and 128 then
    raise exception using errcode = '22023', message = 'Invalid installation ID.';
  end if;
  if pg_catalog.char_length(v_token) not between 16 and 4096 then
    raise exception using errcode = '22023', message = 'Invalid messaging token.';
  end if;
  if v_platform not in ('android', 'ios', 'web', 'macos', 'windows', 'linux') then
    raise exception using errcode = '22023', message = 'Invalid device platform.';
  end if;
  if pg_catalog.char_length(v_source) not between 1 and 64 then
    raise exception using errcode = '22023', message = 'Invalid registration source.';
  end if;

  delete from public.firebase_device_registrations
  where (installation_id = v_installation_id or token = v_token)
    and not (user_id = v_user_id and installation_id = v_installation_id);

  insert into public.firebase_device_registrations (
    user_id,
    installation_id,
    token,
    platform,
    source,
    last_seen_at
  )
  values (
    v_user_id,
    v_installation_id,
    v_token,
    v_platform,
    v_source,
    pg_catalog.clock_timestamp()
  )
  on conflict (installation_id) do update set
    user_id = excluded.user_id,
    token = excluded.token,
    platform = excluded.platform,
    source = excluded.source,
    last_seen_at = excluded.last_seen_at
  returning id into v_registration_id;

  return v_registration_id;
end;
$$;

create or replace function public.unregister_firebase_device(
  p_installation_id text
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_installation_id text := pg_catalog.btrim(p_installation_id);
  v_deleted bigint;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Authentication is required.';
  end if;
  if pg_catalog.char_length(v_installation_id) not between 20 and 128 then
    raise exception using errcode = '22023', message = 'Invalid installation ID.';
  end if;

  delete from public.firebase_device_registrations
  where user_id = v_user_id
    and installation_id = v_installation_id;
  get diagnostics v_deleted = row_count;
  return v_deleted = 1;
end;
$$;

revoke all on function public.register_firebase_device(text, text, text, text)
  from public, anon, authenticated, service_role;
revoke all on function public.unregister_firebase_device(text)
  from public, anon, authenticated, service_role;
grant execute on function public.register_firebase_device(text, text, text, text)
  to authenticated;
grant execute on function public.unregister_firebase_device(text)
  to authenticated;

comment on table public.firebase_device_registrations is
  'Service-readable FCM delivery registrations, one current owner per installation and token.';
comment on function public.register_firebase_device(text, text, text, text) is
  'Claims the caller device and messaging token for auth.uid() without exposing the registration table.';
comment on function public.unregister_firebase_device(text) is
  'Releases only the caller-owned device registration.';

notify pgrst, 'reload schema';
